 Core:[['Crunch',12,'ק״ג',[30,30,23]],['Flutter Kicks',0,'משקל גוף',[30,30,30]],['Heel Touches',0,'משקל גוף',[30,31,35]],['Plank',0,'שניות',[190]]]
